def sum_product(numbers: List[int]) -> Tuple[int, int]:
    if not numbers:
        return (0, 1)

    sum_num = 0
    product_num = 1

    for num in numbers:
        sum_num += num
        product_num *= num

    return (sum_num, product_num)
