std::string string_xor(std::string a, std::string b) {
    // Ensure both strings are of equal length by padding with leading zeros if necessary
    size_t maxLength = std::max(a.length(), b.length());
    a = std::string(maxLength - a.length(), '0') + a;
    b = std::string(maxLength - b.length(), '0') + b;

