def prime_fib(n: int) -> int:
    """
    prime_fib returns the n-th number that is a Fibonacci number and it's also prime.
    """
    def is_prime(x: int) -> bool:
        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    def fibonacci_generator() -> int:
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    prime_fibonacci_numbers = []
    fib_generator = fibonacci_generator()
    while len(prime_fibonacci_numbers) < n:
        num = next(fib_generator)
        if is_prime(num):
