class Solution {
  public int[] pluck(int[] nodes) {
    int minIndex = -1, min = Integer.MAX_VALUE;
    for (int i = 0; i < nodes.length; i++) {
      int num = nodes[i];
      if (num % 2 == 0 && num < min) {
        min = num;
        minIndex = i;
      }
    }
    if (minIndex == -1) {
      return new int[0];
    }
    return new int[]{min, minIndex};
  }
}
