def encode(message):
    vowels = 'aeiou'
    encoded_message = []

    for char in message:
        if char.isalpha():  # Check if the character is a letter
            if char.lower() in vowels:
                # Find the next vowel in the list, wrapping around if necessary
                index = (vowels.index(char.lower()) + 2) % len(vowels)
                # Swap case and replace with the next vowel
                if char.islower():
                    encoded_message.append(vowels[index].upper())
                else:
                    encoded_message.append(vowels[index].lower())
            else:
                # Swap case for non-vowels
