class Solution:
    def topKFrequent(self, nums: List[int], k: int) -> List[int]:
        if not nums or k == 0:
            return []

        counts = {}
        # Add the count of each element to the count dict
        for num in nums:
            if num not in counts:
                counts[num] = 0
            counts[num] += 1

        # heapify the dict to create a min heap of size k
        heap = []
        for num, count in counts.items():
            heapq.heappush(heap, (count, num))
            if len(heap) > k:
                heapq.heappop(heap)

        # convert the heap into a list and sort it in descending order
        heap = sorted(heap, reverse=True)

        # return the last k elements from the heap
        return [num for count, num in heap]

