class Solution:
    def findMinPath(self, grid: List[List[int]], k: int) -> List[int]:
        from heapq import heappop, heappush
        row, col, N = len(grid), len(grid[0]), len(grid) * len(grid[0])

        directions = ((0, 1), (1, 0), (0, -1), (-1, 0))

        def valid(x, y, path):
            if x < 0 or x >= N or y < 0 or y >= N or (x, y) in path:
                return False
            return True

        minHeap = [(grid[0][0], 0, 0)]
        visited = set([(0, 0)])

        while minHeap:
            value, x, y = heappop(minHeap)
            if len(path) == k:
                return path

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if valid(nx, ny, path):
                    visited.add((nx, ny))
                    heappush(minHeap, (grid[nx][ny], nx, ny))

        return []
