def specialFilter(nums):
    def isOdd(num):
        """Check if a digit is odd."""
        return num % 2 != 0

    def firstDigit(num):
        """Get the first digit of a number."""
        return int(str(num)[0])

    def lastDigit(num):
        """Get the last digit of a number."""
        return int(str(num)[-1])

    count = 0
    for num in nums:
        if num > 10:
            if isOdd(firstDigit(num)) and isOdd(lastDigit(num)):
