# Function to check if a number is prime
def is_prime(num):
    # Handle edge cases
    if num <= 1:
        return False
    if num <= 3:
        return True
    # Check divisibility by 2 or 3
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True
```

