    has_letters = any(c.isalpha() for c in s)

    if has_letters:
        # Reverse only the letters in the string
        return ''.join(c.swapcase() if c.isalpha() else c for c in s)
    else:
        # Reverse the entire string if it contains no letters
        return s[::-1]
