from string import ascii_letters

def solve(s):
    # Check if the string contains any letter
    if not any(char in ascii_letters for char in s):
        # If no letters, reverse the string
        return s[::-1]

    # Initialize an empty list to store characters
    l = []

    # Iterate over each character in the string
    for i in s:
        # Check if the character is a letter
        if i in ascii_letters:
            # If letter, reverse its case
            if i.isupper():
                l.append(i.lower())
            else:
                l.append(i.upper())
        else:
            # If not a letter, keep the character as it is
            l.append(i)

    # Join the list into a string and return it
    return ''.join(l)
